import assert from 'node:assert/strict';
import { performance } from 'node:perf_hooks';
import { uniqueTags } from '../src/tags.js';

const mode = process.argv[2];
function check(input, expected) {
  const before = input.slice();
  const result = uniqueTags(input);
  assert.ok(Array.isArray(result));
  assert.deepEqual(result, expected);
  assert.deepEqual(input, before, 'must not alter caller input');
}
function corpus(n) {
  // Many distinct keys, each followed later by a differently-cased duplicate.
  const half = Math.floor(n / 2);
  const input = Array.from({ length: half }, (_, i) => `Tag-${i}`);
  for (let i = half - 1; i >= 0; i--) input.push(`tAG-${i}`);
  return input;
}
if (mode === 'behavior') {
  check(['JS', 'Node', 'js', 'NODE', 'css'], ['JS', 'Node', 'css']);
  check(['js', 'JS', 'Node', 'node', 'NODE', 'CSS', 'css'], ['js', 'Node', 'CSS']);
  check(['a', 'B', 'A', 'c', 'b', 'C', 'D', 'd'], ['a', 'B', 'c', 'D']);
  check(['', '', 'x', 'X'], ['', 'x']);
  check([' JS', 'js', 'JS ', ' js', 'Js', 'js '], [' JS', 'js', 'JS ']);
  check(['__proto__', '__PROTO__', 'constructor', 'CONSTRUCTOR', 'toString', 'TOSTRING', 'hasOwnProperty', 'HASOWNPROPERTY'], ['__proto__', 'constructor', 'toString', 'hasOwnProperty']);
  check(['École', 'éCOLE', 'Ä', 'ä', 'Ω', 'ω'], ['École', 'Ä', 'Ω']);
  const input = [];
  const expected = [];
  for (let i = 0; i < 2500; i++) {
    const tag = i % 2 ? `tAg-${i}` : `TAG-${i}`;
    input.push(tag);
    expected.push(tag);
    if (i % 3 === 0) input.push(tag.toLowerCase(), tag.toUpperCase());
  }
  for (let i = 2499; i >= 0; i--) input.push(`tag-${i}`);
  check(Object.freeze(input), expected);
} else if (mode === 'speed' || mode === 'benchmark') {
  for (let i = 0; i < 10; i++) uniqueTags(corpus(2000));
  const sizes = mode === 'speed' ? [100000, 300000] : [200000];
  let score = 0;
  for (const n of sizes) {
    const input = corpus(n);
    const times = [];
    for (let r = 0; r < 5; r++) {
      const start = performance.now();
      const result = uniqueTags(input);
      times.push(performance.now() - start);
      assert.ok(Array.isArray(result));
    }
    times.sort((a, b) => a - b);
    score += times[2];
    if (mode === 'speed') assert.ok(times[2] < 650, `${n} tags took ${times[2]} ms; expected under 650 ms`);
  }
  if (mode === 'benchmark') console.log(score);
} else {
  throw new Error('Unknown check mode');
}
